cat > /tmp/test-threshold.js << 'EOF'
import { generateReport, runEvaluations } from '/private/tmp/100-tricks-runs/d45a/without/h2-eval-thresholds/r1/packages/frai-core/src/eval/index.js';

// Test 1: Thresholds pass when all metrics meet them
console.log('Test 1: All thresholds pass');
const evaluations1 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report1 = generateReport({
  evaluations: evaluations1,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.5,
    toxicity: 0.5
  }
});
console.log('  passed:', report1.passed);
console.log('  thresholds:', report1.thresholds.map(t => ({ metric: t.metric, passed: t.passed })));

// Test 2: Threshold fails when metric is below minimum
console.log('\nTest 2: Threshold fails');
const evaluations2 = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'goodbye']
});
const report2 = generateReport({
  evaluations: evaluations2,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.9
  }
});
console.log('  passed:', report2.passed);
console.log('  thresholds:', report2.thresholds.map(t => ({ metric: t.metric, passed: t.passed, score: t.score })));

// Test 3: No thresholds
console.log('\nTest 3: No thresholds');
const report3 = generateReport({
  evaluations: evaluations1,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});
console.log('  passed:', report3.passed);
console.log('  thresholds length:', report3.thresholds.length);

console.log('\nAll tests passed!');
EOF
